// ══════════════════════════════════════════════
// Node: Validate & Build Webhook Payload
// ══════════════════════════════════════════════
// Reads incoming webhook body, validates fields,
// and builds a clean { temp, humidity } payload.
// ══════════════════════════════════════════════

const body = $input.first().json.body || $input.first().json;

const temp     = parseFloat(body.temp);
const humidity = parseFloat(body.humidity);

// ── Input validation ──────────────────────────
if (isNaN(temp) || isNaN(humidity)) {
  throw new Error('Validation error: both "temp" (°C) and "humidity" (%) must be numeric.');
}

if (temp < -50 || temp > 60) {
  throw new Error(`Validation error: temp=${temp} is out of range [-50, 60].`);
}

if (humidity < 0 || humidity > 100) {
  throw new Error(`Validation error: humidity=${humidity} is out of range [0, 100].`);
}

console.log(`[Webhook Mapper] temp=${temp} humidity=${humidity}`);

return [{ json: { temp: temp, humidity: humidity, trigger: 'webhook' } }];

// ══════════════════════════════════════════════
// Node: Build Cron Default Payload
// ══════════════════════════════════════════════
// For scheduled runs, generate a simulated sensor
// reading (or pull from a database/API in production).
// Here we randomise within a realistic range to
// demonstrate a real automated pipeline.
// ══════════════════════════════════════════════

// Simulate sensor reading (replace with DB/API call in production)
const temp     = parseFloat((Math.random() * 35 + 5).toFixed(2));   // 5°C – 40°C
const humidity = parseFloat((Math.random() * 60 + 20).toFixed(2));  // 20% – 80%

console.log(`[Cron Scheduler] Auto-generated reading — temp=${temp} humidity=${humidity}`);

return [{ json: { temp, humidity, trigger: 'cron' } }];

// ══════════════════════════════════════════════
// Node: Format & Log Successful Prediction
// ══════════════════════════════════════════════
// Normalises the FastAPI response and attaches
// execution metadata for downstream storage.
// ══════════════════════════════════════════════

const item = $input.first().json;
const resp = item.body || item;

const record = {
  timestamp:    new Date().toISOString(),
  trigger:      item.trigger || 'webhook',
  status:       'success',
  input: {
    temp:     resp.input?.temp     ?? null,
    humidity: resp.input?.humidity ?? null
  },
  prediction:   resp.prediction,
  latency_ms:   resp.latency_ms,
  model_source: resp.model_source || 'unknown'
};

console.log(`[Success Logger] prediction=${record.prediction} latency=${record.latency_ms}ms trigger=${record.trigger}`);

return [{ json: record }];

