// ══════════════════════════════════════════════
// Node: Handle & Log Prediction Error
// ══════════════════════════════════════════════
// Extracts error details from FastAPI response
// or from n8n's own error object, logs everything
// for diagnostics, and returns a structured record.
// ══════════════════════════════════════════════

const item  = $input.first();
const body  = item.json?.body  || item.json || {};
const error = item.json?.error || item.error || {};

const httpStatus  = item.json?.statusCode || body.statusCode || 'unknown';
const errorDetail = body.detail || error.message || body.message || 'Unknown error from ML backend';
const trigger     = item.json?.trigger || body.trigger || 'webhook';

console.error(
  `[Error Handler] trigger=${trigger} http_status=${httpStatus} ` +
  `detail="${errorDetail}"`
);

return [{
  json: {
    timestamp:    new Date().toISOString(),
    trigger,
    status:       'error',
    http_status:  httpStatus,
    error_detail: errorDetail,
    input: {
      temp:     item.json?.temp     ?? null,
      humidity: item.json?.humidity ?? null
    },
    prediction:  null
  }
}];

// ══════════════════════════════════════════════
// Node: Save Prediction to JSON File
// ══════════════════════════════════════════════
// Appends the prediction record to predictions.json
// via FastAPI's /predictions endpoint (GET to read,
// or rely on FastAPI's own auto-save on /predict).
//
// In n8n we confirm storage by calling GET /predictions
// and logging the updated total count.
// Note: The actual file write happens inside FastAPI.
// ══════════════════════════════════════════════

const record = $input.first().json;

// The FastAPI /predict endpoint automatically saves to predictions.json.
// Here we just enrich the record with n8n execution metadata.
const enriched = {
  ...record,
  n8n_execution_id: $execution?.id  || 'manual',
  n8n_workflow:     $workflow?.name  || 'ESPRIT ML Rubric Workflow',
  saved_at_n8n:     new Date().toISOString()
};

console.log(
  `[Storage Confirm] timestamp=${enriched.timestamp} ` +
  `prediction=${enriched.prediction} trigger=${enriched.trigger}`
);

return [{ json: enriched }];
